PRAGMA foreign_keys = ON;
CREATE TABLE categoria (id INTEGER PRIMARY KEY AUTOINCREMENT,codigo TEXT NOT NULL COLLATE NOCASE UNIQUE,nombre TEXT NOT NULL COLLATE NOCASE UNIQUE,activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)),fecha_alta TEXT NOT NULL);
CREATE TABLE subcategoria (id INTEGER PRIMARY KEY AUTOINCREMENT,categoria_id INTEGER NOT NULL,codigo TEXT NOT NULL COLLATE NOCASE,nombre TEXT NOT NULL COLLATE NOCASE,activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)),fecha_alta TEXT NOT NULL,FOREIGN KEY(categoria_id) REFERENCES categoria(id),UNIQUE(categoria_id,codigo),UNIQUE(categoria_id,nombre));
CREATE TABLE estado_peticion (id INTEGER PRIMARY KEY AUTOINCREMENT,codigo TEXT NOT NULL COLLATE NOCASE UNIQUE,nombre TEXT NOT NULL COLLATE NOCASE UNIQUE,color TEXT,orden INTEGER NOT NULL DEFAULT 0,activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)),estado_final INTEGER NOT NULL DEFAULT 0 CHECK(estado_final IN(0,1)));
CREATE TABLE estado_horas (id INTEGER PRIMARY KEY AUTOINCREMENT,codigo TEXT NOT NULL COLLATE NOCASE UNIQUE,nombre TEXT NOT NULL COLLATE NOCASE UNIQUE,color TEXT,orden INTEGER NOT NULL DEFAULT 0,activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)),estado_final INTEGER NOT NULL DEFAULT 0 CHECK(estado_final IN(0,1)));
CREATE TABLE usuario (id INTEGER PRIMARY KEY AUTOINCREMENT,codigo TEXT NOT NULL COLLATE NOCASE UNIQUE,nombre TEXT NOT NULL,email TEXT,activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)));
CREATE TABLE tipo_documento (id INTEGER PRIMARY KEY AUTOINCREMENT,nombre TEXT NOT NULL COLLATE NOCASE UNIQUE,orden INTEGER NOT NULL DEFAULT 0,activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)));
CREATE TABLE peticion (id INTEGER PRIMARY KEY AUTOINCREMENT,codigo TEXT NOT NULL COLLATE NOCASE UNIQUE,asunto TEXT NOT NULL,descripcion TEXT,categoria_id INTEGER NOT NULL,subcategoria_id INTEGER NOT NULL,usuario_id INTEGER NOT NULL,estado_actual_id INTEGER NOT NULL,fecha_alta TEXT NOT NULL,fecha_inicio_prevista TEXT,fecha_fin_prevista TEXT,fecha_inicio_real TEXT,fecha_fin_real TEXT,horas_previstas NUMERIC,horas_reales NUMERIC NOT NULL DEFAULT 0,porcentaje NUMERIC NOT NULL DEFAULT 0 CHECK(porcentaje>=0 AND porcentaje<=100),ruta_documentos TEXT,activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)),FOREIGN KEY(categoria_id) REFERENCES categoria(id),FOREIGN KEY(subcategoria_id) REFERENCES subcategoria(id),FOREIGN KEY(usuario_id) REFERENCES usuario(id),FOREIGN KEY(estado_actual_id) REFERENCES estado_peticion(id));
CREATE TABLE peticion_estado (id INTEGER PRIMARY KEY AUTOINCREMENT,peticion_id INTEGER NOT NULL,estado_anterior_id INTEGER,estado_nuevo_id INTEGER NOT NULL,fecha_cambio TEXT NOT NULL,usuario_id INTEGER NOT NULL,observaciones TEXT NOT NULL CHECK(length(trim(observaciones))>0),FOREIGN KEY(peticion_id) REFERENCES peticion(id) ON DELETE CASCADE,FOREIGN KEY(estado_anterior_id) REFERENCES estado_peticion(id),FOREIGN KEY(estado_nuevo_id) REFERENCES estado_peticion(id),FOREIGN KEY(usuario_id) REFERENCES usuario(id));
CREATE TABLE imputacion (id INTEGER PRIMARY KEY AUTOINCREMENT,peticion_id INTEGER NOT NULL,usuario_id INTEGER NOT NULL,fecha TEXT NOT NULL,horas NUMERIC NOT NULL CHECK(horas>0),extra INTEGER NOT NULL DEFAULT 0 CHECK(extra IN(0,1)),estado_horas_id INTEGER NOT NULL,descripcion TEXT,fecha_alta TEXT NOT NULL,FOREIGN KEY(peticion_id) REFERENCES peticion(id),FOREIGN KEY(usuario_id) REFERENCES usuario(id),FOREIGN KEY(estado_horas_id) REFERENCES estado_horas(id));
CREATE TABLE documento (id INTEGER PRIMARY KEY AUTOINCREMENT,peticion_id INTEGER NOT NULL,tipo_documento_id INTEGER NOT NULL,nombre TEXT NOT NULL,ruta TEXT NOT NULL,descripcion TEXT,fecha_alta TEXT NOT NULL,usuario_id INTEGER NOT NULL,FOREIGN KEY(peticion_id) REFERENCES peticion(id),FOREIGN KEY(tipo_documento_id) REFERENCES tipo_documento(id),FOREIGN KEY(usuario_id) REFERENCES usuario(id));
CREATE TABLE preferencia_usuario (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL UNIQUE,ultima_ruta_documentos TEXT,filtros_peticiones TEXT,columnas_visibles TEXT,orden_columnas TEXT,ancho_columnas TEXT,densidad TEXT,ultimo_usuario_id INTEGER,ultima_peticion_id INTEGER,pestana_activa TEXT,tema TEXT,FOREIGN KEY(usuario_id) REFERENCES usuario(id) ON DELETE CASCADE,FOREIGN KEY(ultimo_usuario_id) REFERENCES usuario(id),FOREIGN KEY(ultima_peticion_id) REFERENCES peticion(id));
CREATE INDEX idx_peticion_estado ON peticion(estado_actual_id);
CREATE INDEX idx_peticion_categoria ON peticion(categoria_id);
CREATE INDEX idx_peticion_usuario ON peticion(usuario_id);
CREATE INDEX idx_imputacion_peticion_fecha ON imputacion(peticion_id,fecha);
CREATE INDEX idx_historial_peticion_fecha ON peticion_estado(peticion_id,fecha_cambio);
CREATE INDEX idx_documento_peticion ON documento(peticion_id);
